fn solve(n: i8, s: i8, a: Vec<i8>) -> i8 {
    // The result is 1 exactly when n == 1 and the only element equals s.
    // In all other situations, including when n > 1 or the only element != s,
    // we return 0.
    if n == 1 && a.len() == 1 && a[0] == s {
        1
    } else {
        0
    }
}

